"""Fixed Chinese fixtures for parser and chunk metadata contracts."""

from __future__ import annotations

import base64
from pathlib import Path

CHINESE_PDF_B64 = """"""


def write_chinese_pdf(path: Path) -> Path:
    """Write a checked-in, extractable Chinese PDF fixture."""
    path.write_bytes(base64.b64decode(CHINESE_PDF_B64))
    return path


def write_chinese_docx(path: Path) -> Path:
    """Write a deterministic Chinese DOCX fixture with nested headings."""
    from docx import Document

    document = Document()
    document.add_heading("第一章 线性代数", level=1)
    document.add_heading("第一节 矩阵", level=2)
    document.add_paragraph("矩阵用于表示线性变换。")
    document.add_paragraph("矩阵的行和列共同描述数据的结构。")
    document.add_heading("第二节 向量空间", level=2)
    document.add_paragraph("向量空间具有加法和数乘结构。")
    document.save(path)
    return path


def write_chinese_pptx(path: Path) -> Path:
    """Write a deterministic Chinese PPTX fixture with slide titles."""
    from pptx import Presentation

    presentation = Presentation()
    first = presentation.slides.add_slide(presentation.slide_layouts[1])
    first.shapes.title.text = "第一节 矩阵"
    first.placeholders[1].text = "矩阵用于表示线性变换。"
    second = presentation.slides.add_slide(presentation.slide_layouts[1])
    second.shapes.title.text = "第二节 特征值"
    second.placeholders[1].text = "特征值描述矩阵作用下的特殊方向。"
    presentation.save(path)
    return path
